Lemma FT_of_internal : forall m,
  rw_cells usegs m G_FIELD_TABLE FTCells -> rw_cells usegs m G_FIELD_TABLE_GUARD (hg_cells 1 1 (zeros 6)) -> FT m.
Proof.
  intros m C1 C2. split; [exact C1|]. unfold FTGuardCells.
  eapply rw_cells_reshape; [exact C2 | cbn; repeat split; reflexivity | vm_compute; reflexivity].
Qed.

